import{_ as s,C as a,o as n,c as r,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/picker-runs.png",c="/screenshots/picker-runs-live.png",p="/screenshots/picker-runs-ci.png",v=JSON.parse(`{"title":"Runs window","description":"Piwi Picker's Runs window follows the tests your editor runs, from a window beside them: pause, step, resume and end them, write code from a stop, watch a test's page live while it runs, click and type on it at a stop, pick a locator on its image, and share a run live with your team.","frontmatter":{"title":"Runs window","description":"Piwi Picker's Runs window follows the tests your editor runs, from a window beside them: pause, step, resume and end them, write code from a stop, watch a test's page live while it runs, click and type on it at a stop, pick a locator on its image, and share a run live with your team.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/runs-window.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/runs-window.html"}],["meta",{"property":"og:title","content":"Runs window | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Piwi Picker's Runs window follows the tests your editor runs, from a window beside them: pause, step, resume and end them, write code from a stop, watch a test's page live while it runs, click and type on it at a stop, pick a locator on its image, and share a run live with your team."}]]},"headers":[],"relativePath":"features/runs-window.md","filePath":"features/runs-window.md","lastUpdated":1794595265000}`),w={name:"features/runs-window.md"};function u(g,e,m,f,k,y){const o=a("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"runs-window",tabindex:"-1"},[i("Runs window "),t("a",{class:"header-anchor",href:"#runs-window","aria-label":'Permalink to "Runs window"'},"​")],-1)),h(o,{reporter:"",fixtures:"",extension:""}),e[1]||(e[1]=d('<p>Piwi Picker&#39;s Runs window, a window of its own beside the test&#39;s browser, follows the runs VS Code or a JetBrains IDE starts: it pauses, steps and resumes them, writes code from a stop through the editor and, for a headless or remote test, shows its page live, takes your clicks and keys on it, and picks a locator on its image. The editor shows the same stops: <a href="./editor-run-control.html">Pause and step from the editor</a>.</p><h2 id="open-it" tabindex="-1">Open it <a class="header-anchor" href="#open-it" aria-label="Permalink to &quot;Open it&quot;">​</a></h2><p>With Piwi Picker <a href="./editor-recording.html#send-from-piwi-picker">paired with VS Code or a JetBrains IDE</a>, or with the <a href="./bug-reports.html#running-it-with-playwright-in-the-desktop-app">desktop app</a>, the popup shows a <strong>Runs</strong> tile under <strong>More tools</strong>, muted with <strong>Not connected</strong> while none of them answers. It opens the Runs window where you left it last. While a test waits at a stop for you (a breakpoint, a <strong>Pause</strong>, a failure held at its line, not a stop an agent drives), the tile says how many in amber, as do the toolbar&#39;s badge and the Runs window&#39;s title (<code>1 waiting · Runs · Piwi Picker</code>); while none waits, how many failed, in red, a run that failed while the Runs window was not in front counted until you bring it there. For each run the editor <a href="./editor-runs.html">started</a>: its folder and command, how many of its tests ended (<code>3 of 9 tests · 1 failed</code>), then each worker&#39;s test and whether it runs or where it stopped (the file and line, the call about to run, an image of the page). A run that ended says how: passed, failed with its first failure, timed out or interrupted. The count and the outcome need <code>@piwitests/reporter</code> newer than 0.67.0. A run without <a href="#watch-live"><strong>Watch</strong></a> and no test stopped says how one stops: a breakpoint, a <code>page.pause()</code> or <strong>Pause</strong>. A run <a href="./terminal-runs.html">started outside Piwi</a> shows too, marked <strong>Terminal</strong> or <strong>Test runner</strong>. <a href="./watch-running-test.html#a-ci-run-of-your-branch">CI runs</a> show read-only, with <strong>Watch</strong> on a running test.</p><h2 id="the-controls" tabindex="-1">The controls <a class="header-anchor" href="#the-controls" aria-label="Permalink to &quot;The controls&quot;">​</a></h2><p><strong>Pause</strong> stops a running test before its next call; while the test waits in a long one, its row says which (a locator call, for how long), with <a href="./end-the-test.html#while-a-pause-waits-for-a-call"><strong>End the test</strong></a>. At a stop, <strong>Resume</strong>, <strong>Step</strong>, <strong>Finish</strong> and <a href="./end-the-test.html"><strong>End the test</strong></a> do what they do <a href="./editor-run-control.html#the-controls">in the editor</a>; Run to cursor stays in the editor. A live run of several workers shows one at a time, behind tabs marked with their state, with <strong>Pause all</strong> and <strong>Resume all</strong> under its name. A new stop takes the tab from a worker neither stopped nor watched, and <strong>Resume</strong> or <strong>End the test</strong> moves it to the next stopped test. <strong>Stop the run</strong> ends a run an editor or the desktop app started, not a terminal&#39;s or test runner&#39;s. Resume, Step and Finish have <a href="/reference/keyboard-shortcuts.html#piwi-picker-s-runs-window">keys</a>, and the <a href="/reference/keyboard-shortcuts.html#the-run-shortcut">run shortcut</a> resumes or pauses every run from any window.</p><p>A failing test is held at its line, a headless one while its run&#39;s <a href="/guide/concepts.html#hold-failures"><strong>Hold failures</strong></a>, a switch on each run, is on: <strong>Failed at</strong> in red, its error under it. <strong>Resume</strong> lets it end as it failed; <strong>Pick</strong> replaces the failing locator.</p><p><strong>Share live</strong>, under the run&#39;s name, shares the run with your team: <a href="./share-live.html">Share a run live</a>.</p><p>Each run names who else has it open (<strong>Also open in the desktop app</strong>, <strong>An agent follows this run</strong>), and each worker who watches its page (<strong>Watched by you and Visual Studio Code</strong>). One tool drives a stop at a time: an agent that paused it or acts on it, else the last whose person clicked, typed or picked there. While another tool drives it or an agent follows the run, <strong>Take control</strong> makes it yours: an agent&#39;s actions there are refused until you <strong>Give back</strong>. A stop an agent asked for reads <strong>Paused by the agent</strong>: <a href="/guide/concepts.html#presence-driving-a-stop">driving a stop</a>.</p><h2 id="code-from-a-stop" tabindex="-1">Code from a stop <a class="header-anchor" href="#code-from-a-stop" aria-label="Permalink to &quot;Code from a stop&quot;">​</a></h2><p>The actions under <strong>Code</strong> (the last two in <strong>More</strong> once five show) send code to the editor, which writes it at the stopped line, when its Piwi extension and your reporter take them. <strong>Pick</strong> and <strong>Record</strong> start the pause bar&#39;s <strong>Pick a locator</strong> and <strong>Record here</strong>, <strong>Assert</strong> the recorder&#39;s <strong>Check an element</strong>, and <strong>Assert a region</strong> a pick whose ARIA snapshot becomes <code>toMatchAriaSnapshot</code>. They run in the test&#39;s page: where the pause bar shows, or, at a headless stop you <a href="#watch-live">watch</a>, through the view; else they show held, saying <strong>Watch to use</strong>. <strong>Mock a request</strong> lists the page&#39;s fetch and XHR requests, credentials hidden: the one you choose becomes a <code>page.route</code>. Under the test, the window says the code went to the editor, with what to review in it, or why not.</p><figure><img src="'+l+'" alt="The Runs window beside a shop page stopped before a click on Checkout: the test, a card saying where it stopped with the call and its place, its controls and code actions, then the image of the page"><figcaption>The Runs window, beside a test stopped at a breakpoint.</figcaption></figure><h2 id="watch-live" tabindex="-1">Watch a test <a class="header-anchor" href="#watch-live" aria-label="Permalink to &quot;Watch a test {#watch-live}&quot;">​</a></h2><p><strong>Watch</strong>, on a worker&#39;s row, shows its test&#39;s page as it paints, running or stopped, and <strong>Pause and watch</strong> pauses it too: <a href="./watch-running-test.html">Watch a running test</a>. The last frame stays, marked <strong>Running…</strong>, until the next one comes. An older reporter&#39;s row says to update it; with one newer than 0.61.0, its stops have their own <strong>Watch</strong>, which watches each stop alone and, left on, the worker&#39;s next ones.</p><p>The view fills the window&#39;s width, ten frames a second at most, under a red <strong>Live</strong> badge. Only the window that asked gets the frames, stored nowhere, from the test&#39;s worker through the editor service and the extension&#39;s background worker, on your machine or the port your IDE forwards from a <a href="/guide/remote-development.html">remote window</a>. Watching ends when you turn it off, the run ends or you close the window, and pauses while the window is minimized or the editor is out of reach.</p><p>Under the page, from a reporter newer than 0.68.0, the window shows what pixels cannot, as the editor does (<a href="./watch-running-test.html#beside-the-image">beside the image</a>): <strong>Why it waits</strong>, <strong>Events</strong>, <strong>Text</strong> (<strong>Show the page&#39;s text</strong> reads it at each test, secret fields hidden, then follows the test&#39;s trace) and <strong>Filmstrip</strong> (a click enlarges an image, with its call), kept in memory alone. <strong>Open the trace so far</strong>, in a watched page&#39;s head, opens Playwright&#39;s trace viewer on the running test&#39;s trace up to now, on the machine the run runs on, with a reporter newer than 0.68.0: <a href="./watch-running-test.html#open-the-trace-so-far">Watch a running test</a>.</p><p>At a headless stop, which nobody sees, the picker, the recorder&#39;s panel and the check panel appear in the watched view, answered there as in a headed browser; their code reaches the editor the same way.</p><figure><img src="'+c+'" width="488" alt="The Runs window at a headless stop, watching the shop page live: Watch and Interact pressed in the page card&#39;s head, the Live badge on the view, the picker over the page, with Resume, Step and Finish in one group, End the test apart, and Pick, Record, Assert and More under Code"><figcaption>A headless test&#39;s page watched live, with Pick started in it.</figcaption></figure><figure><img src="'+p+'" width="488" alt="The Runs window listing CI run #78 on main with its two running tests, each with Watch and Watch on the dashboard, the second watched: its page live under a Live badge, with the call it is at"><figcaption>A CI run&#39;s test, watched read-only.</figcaption></figure><h2 id="click-and-type-on-the-view" tabindex="-1">Click and type on the view <a class="header-anchor" href="#click-and-type-on-the-view" aria-label="Permalink to &quot;Click and type on the view&quot;">​</a></h2><p>While you watch, <a href="./watch-running-test.html#interact"><strong>Interact</strong></a>, beside <strong>Watch</strong>, sends your pointer, wheel and keys on the view to the page as a person&#39;s would, the picker and the recorder included. Which reach the page, a paste included, and which stay the window&#39;s: the <a href="/reference/keyboard-shortcuts.html#piwi-picker-s-runs-window">keyboard shortcuts</a>.</p><p>A hint under the view says so the first time. What you hold down is let go before the test goes on.</p><h2 id="pick-on-the-image" tabindex="-1">Pick on the image <a class="header-anchor" href="#pick-on-the-image" aria-label="Permalink to &quot;Pick on the image&quot;">​</a></h2><p><strong>Pick on the image</strong>, above the image, or a <code>Shift</code>+click on the image or the view, names the element a click under the pointer would reach (a dialog or a banner over the page included), without touching the page: the locator the pause bar&#39;s <strong>Pick a locator</strong> would rank first for it, sent to the editor in place of the stopped line&#39;s. The window shows it, or why there is none, with <strong>Copy</strong> when no editor took it, on a headed stop&#39;s image too. <code>Esc</code> turns it off. It needs Playwright 1.60 or later, and says so on an older one.</p><h2 id="the-desktop-app-s-runs" tabindex="-1">The desktop app&#39;s runs <a class="header-anchor" href="#the-desktop-app-s-runs" aria-label="Permalink to &quot;The desktop app&#39;s runs&quot;">​</a></h2><p><a href="./bug-reports.html#running-it-with-playwright-in-the-desktop-app">Paired</a> with the <a href="./desktop.html">desktop app</a>, the window lists the runs the app starts beside your editor&#39;s, marked <strong>Desktop app</strong>: reproductions, bisect steps and bug reports included, with the same controls and live view, and its failures to reach the app name the app (<strong>Not connected to the desktop app</strong>). With no editor paired, it follows the app alone. The app holds no editor, so <strong>Pick</strong>, <strong>Record</strong> and <strong>Assert</strong> in the test&#39;s window are not offered; the code of <strong>Assert a region</strong> and <strong>Mock a request</strong> goes to the app&#39;s window to copy, as the window here says: <a href="./desktop-runs.html">Desktop app runs</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>The top frame.</strong> Pick on the image refuses an element inside an iframe.</li><li><strong>What a view shows.</strong> A test&#39;s own screencast, a heavy page, a popup, a download and a dialog: <a href="./watch-running-test.html#limits">Watch a running test</a>.</li><li><strong>The middle button stays the window&#39;s.</strong> It would open a link in a tab the view does not show; <code>Shift</code>+click picks instead of clicking.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the controls and the paused line, in the editor.</li><li><a href="./editor-stop-code.html">Code from a pause</a>: what each action writes, and where.</li><li><a href="./extension.html">Browser extension</a>: Piwi Picker&#39;s other tools, and its permissions.</li><li><a href="/guide/remote-development.html">Remote development</a>: the runs of a dev container or a remote window.</li><li><a href="./editor-pairing.html">Piwi Picker and your editor</a>: how the pairing reaches each editor window and the desktop app, on your machine alone.</li></ul>',29))])}const P=s(w,[["render",u]]);export{v as __pageData,P as default};
